// SPDX-License-Identifier: MIT
// The generator of every tool's licence configuration from the one policy file (PG-D3; T1 R8):
// it writes them, writes them the same way every time, catches drift, refuses a licence the
// policy does not allow (printing the deny reason), and refuses a profile still at the template
// placeholder. Every case names the break it catches.

import assert from "node:assert/strict";
import { existsSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";
import { test } from "node:test";
import { SCRIPTS, run } from "./helpers.mjs";
import { RENDERERS, compilePolicy, render } from "../licence-configs.mjs";

const REPO = resolve(SCRIPTS, "..", "..");
const TEMPLATE = JSON.parse(readFileSync(join(REPO, ".github", "licence-policy.json"), "utf8"));
const HEADED = ["deny.toml", "about.toml", ".github/dependency-review-config.yml", ".github/nuget-license/allowed-licenses.json"];
// nuget-license's override and mapping files are bare JSON and carry no header (licence-configs.mjs).
const BARE = [".github/nuget-license/overrides.json", ".github/nuget-license/licensefile-mappings.json"];
// Every file the generator can write. An adopting repository trims its policy's `generate` list to the
// stacks it uses (README, "Adopting it"), so nothing below reads that list: each test writes a temporary
// policy that names every renderer (B0-U01).
const OUTPUTS = Object.keys(RENDERERS);
const SHA = "b".repeat(64);
// The per-repository lists start empty in every case: an adopting repository fills them with its own
// entries (own_sources for the kit crates, a NuGet clarification), and its own entries must not change a
// case. A case that needs one passes it through `extra` (B0-U01). The `rust` settings are per-repository too (a
// second target, a git source, an ignored advisory), so they start from the template's one target and no exception.
const RUST = { ...structuredClone(TEMPLATE.rust), targets: ["x86_64-pc-windows-gnullvm"], allow_git: [], advisories_ignore: [] };
const policyFor = (profile = "gpl", extra = {}) => ({ ...structuredClone(TEMPLATE), profile, generate: OUTPUTS, own_sources: [], clarifications: [], class_overrides: [], lgpl_dynamic: [], allow_ghsas: [], rust: structuredClone(RUST), ...extra });
const PLACEHOLDER_PROFILE = `{{${"tpl:LICENCE_PROFILE"}}}`; // built at run time so this file carries no placeholder of its own

function repo(policy) {
  const dir = mkdtempSync(join(tmpdir(), "licence-configs-test-"));
  mkdirSync(join(dir, ".github"), { recursive: true });
  writeFileSync(join(dir, ".github", "licence-policy.json"), JSON.stringify(policy, null, 2));
  return {
    dir,
    gen: (mode) => run("licence-configs.mjs", [mode], dir),
    read: (path) => readFileSync(join(dir, path), "utf8"),
    write: (path, text) => writeFileSync(join(dir, path), text),
    cleanup: () => rmSync(dir, { recursive: true, force: true }),
  };
}

test("--write generates the six configs; each that can hold a comment has a do-not-edit header naming the generator and profile", () => {
  const r = repo(policyFor("gpl"));
  try {
    const w = r.gen("--write");
    assert.equal(w.code, 0, w.out);
    for (const path of OUTPUTS) assert.ok(r.read(path).endsWith("\n"), `${path} ends with a newline`);
    assert.deepEqual(JSON.parse(r.read(".github/nuget-license/overrides.json")), [], "no NuGet clarification, no override");
    assert.deepEqual(JSON.parse(r.read(".github/nuget-license/licensefile-mappings.json")), {}, "no NuGet clarification, no mapping");
    for (const path of HEADED) {
      const text = r.read(path);
      assert.match(text, /Generated by \.github\/scripts\/licence-configs\.mjs from \.github\/licence-policy\.json/, path);
      assert.match(text, /\(profile gpl\)\. Do not edit/, path);
      assert.ok(text.endsWith("\n"), `${path} ends with a newline`);
    }
    const deny = r.read("deny.toml");
    assert.match(deny, /allow = \[\n {2}"MIT",/);
    assert.match(deny, /"GPL-3\.0-or-later",/);
    assert.match(deny, /\[\[bans\.features\]\]\ncrate = "eframe"\ndeny = \["default_fonts"\]/, "the PG-D6 font rule");
    assert.match(deny, /\{ crate = "openh264", reason = "H\.264 and HEVC codecs: denied component/, "the PG-D31 floor");
    assert.match(deny, /targets = \["x86_64-pc-windows-gnullvm"\]/);
    assert.doesNotMatch(deny.replace(/^#.*$/gm, ""), /LicenseRef-PD-USGov|Ubuntu-font|AGPL/, "no record-only id, no denied id");
    assert.match(r.read("about.toml"), /accepted = \[\n {2}"MIT",/);
    const review = r.read(".github/dependency-review-config.yml");
    assert.match(review, /allow-licenses:\n {2}- 'MIT'/);
    assert.match(review, /deny-packages:[\s\S]*- 'pkg:npm\/%40ffmpeg-installer\/ffmpeg'/);
    assert.doesNotMatch(review, /deny-licenses/);
    const nuget = JSON.parse(r.read(".github/nuget-license/allowed-licenses.json"));
    assert.match(nuget[0], /^Generated by .*names no licence\.$/);
    assert.ok(nuget.includes("Apache-2.0") && nuget.includes("GPL-3.0-or-later"));
  } finally {
    r.cleanup();
  }
});

test("the profile decides class L: gpl-le configs carry no GPL or AGPL entry (T1 R9)", () => {
  const files = render(compilePolicy(policyFor("gpl-le")));
  for (const path of ["deny.toml", "about.toml", ".github/dependency-review-config.yml"]) {
    assert.doesNotMatch(files[path].replace(/^#.*$/gm, ""), /"?'?(L|A)?GPL-/, path);
  }
  assert.match(files["deny.toml"], /\(profile gpl-le\)/);
});

test("the output is deterministic, and --check passes right after --write", () => {
  const r = repo(policyFor("gpl"));
  try {
    r.gen("--write");
    const first = OUTPUTS.map(r.read);
    assert.equal(r.gen("--write").code, 0);
    assert.deepEqual(OUTPUTS.map(r.read), first);
    const c = r.gen("--check");
    assert.equal(c.code, 0, c.out);
    assert.match(c.out, /6 generated licence config\(s\) match/);
    r.write("deny.toml", first[0].replaceAll("\n", "\r\n"));
    assert.equal(r.gen("--check").code, 0, "a CRLF checkout is not drift");
  } finally {
    r.cleanup();
  }
});

test("--check fails on a hand edit or a missing file and names it", () => {
  const r = repo(policyFor("gpl"));
  try {
    r.gen("--write");
    r.write("about.toml", r.read("about.toml").replace('"MIT",', '"MIT",\n  "SSPL-1.0",'));
    rmSync(join(r.dir, ".github", "dependency-review-config.yml"));
    const c = r.gen("--check");
    assert.equal(c.code, 1, c.out);
    assert.match(c.out, /about\.toml differs from what the policy generates, first at line \d+/);
    assert.match(c.out, /\.github\/dependency-review-config\.yml is missing/);
    assert.match(c.out, /Run node \.github\/scripts\/licence-configs\.mjs --write/);
  } finally {
    r.cleanup();
  }
});

test("every file the generator can write is classed here as headed or bare, and the policy's generate list names only renderers; in the unadopted template it names all of them (B0-U01)", () => {
  assert.deepEqual([...HEADED, ...BARE].sort(), [...OUTPUTS].sort(), "a new renderer must be classed in HEADED or BARE, so the drift and profile cases below cover it");
  for (const f of TEMPLATE.generate) assert.ok(OUTPUTS.includes(f), `${f} in the policy's generate list has no renderer`);
  // An adopting repository drops the files its stacks do not use from `generate`; only the template
  // itself, whose profile is still the placeholder, must list every renderer.
  if (TEMPLATE.profile === PLACEHOLDER_PROFILE) assert.deepEqual([...TEMPLATE.generate].sort(), [...OUTPUTS].sort(), "the template's generate list names every renderer");
});

test("a changed first line, a changed last line, an extra trailing newline or a missing final newline in any one generated file makes --check exit 1 and name that file; restored, it exits 0 (B0-U01)", () => {
  for (const profile of ["gpl", "gpl-le"]) {
    const r = repo(policyFor(profile));
    try {
      assert.equal(r.gen("--write").code, 0);
      for (const path of OUTPUTS) {
        const original = r.read(path);
        const lines = original.split("\n"); // the file ends with "\n", so the last entry is empty
        const lastLine = lines.length - 1; // 1-based number of the last real line
        // A word added to the first or the last line, and a single trailing space on the first line (white space is drift).
        for (const [line, added] of [[1, " DRIFT"], [lastLine, " DRIFT"], [1, " "]]) {
          const planted = lines.map((l, i) => (i === line - 1 ? `${l}${added}` : l)).join("\n");
          r.write(path, planted);
          const c = r.gen("--check");
          assert.equal(c.code, 1, `${profile} ${path} line ${line}: ${c.out}`);
          assert.ok(c.out.includes(`- ${path} differs from what the policy generates, first at line ${line}`), `${profile} ${path} line ${line} is not named:\n${c.out}`);
          for (const other of OUTPUTS.filter((x) => x !== path)) assert.ok(!c.out.includes(`- ${other} `), `${other} is wrongly named for a drift in ${path}`);
          r.write(path, original);
          assert.equal(r.gen("--check").code, 0, `${profile} ${path}: restored`);
        }
        // The end of the file counts too: an extra blank line at the end, or no final newline, is drift (B0-U01). The line
        // reported is a line of the file: the extra blank line is the one after the last, and a missing newline is the last
        // line's, never a line past the end.
        for (const [what, planted, at] of [["an extra trailing newline", `${original}\n`, lastLine + 1], ["no final newline", original.replace(/\n$/, ""), lastLine]]) {
          r.write(path, planted);
          const c = r.gen("--check");
          assert.equal(c.code, 1, `${profile} ${path} with ${what}: ${c.out}`);
          assert.ok(c.out.includes(`- ${path} differs from what the policy generates, first at line ${at}\n`), `${profile} ${path} with ${what} is not named at line ${at}:\n${c.out}`);
          r.write(path, original);
          assert.equal(r.gen("--check").code, 0, `${profile} ${path}: restored after ${what}`);
        }
        rmSync(join(r.dir, path));
        const gone = r.gen("--check");
        assert.equal(gone.code, 1, `${profile} ${path}: ${gone.out}`);
        assert.ok(gone.out.includes(`- ${path} is missing`), gone.out);
        r.write(path, original);
      }
    } finally {
      r.cleanup();
    }
  }
});

test("--write then --check exits 0 for each of the four profiles, and every profile's own name is in its headers (B0-U01)", () => {
  for (const profile of ["gpl", "gpl-le", "reserved", "permissive"]) {
    const r = repo(policyFor(profile));
    try {
      assert.equal(r.gen("--write").code, 0, profile);
      const c = r.gen("--check");
      assert.equal(c.code, 0, `${profile}: ${c.out}`);
      assert.match(c.out, new RegExp(`\\(profile ${profile}\\)`));
      for (const path of HEADED) assert.match(r.read(path), new RegExp(`\\(profile ${profile}\\)\\. Do not edit`), `${profile} ${path}`);
    } finally {
      r.cleanup();
    }
  }
});

test("--check fails when the policy changes and the configs were not regenerated", () => {
  const policy = policyFor("gpl");
  const r = repo(policy);
  try {
    r.gen("--write");
    policy.allow.L.common.push("X11");
    r.write(".github/licence-policy.json", JSON.stringify(policy));
    const c = r.gen("--check");
    assert.equal(c.code, 1, c.out);
    assert.match(c.out, /deny\.toml differs/);
  } finally {
    r.cleanup();
  }
});

test("only the files the policy lists in `generate` are written and checked", () => {
  const r = repo(policyFor("gpl", { generate: [".github/dependency-review-config.yml"] }));
  try {
    assert.equal(r.gen("--write").code, 0);
    assert.ok(!existsSync(join(r.dir, "deny.toml")));
    assert.equal(r.gen("--check").code, 0);
  } finally {
    r.cleanup();
  }
});

test("clarifications and class overrides reach cargo-deny and cargo-about", () => {
  const files = render(
    compilePolicy(
      policyFor("gpl", {
        clarifications: [{ ecosystem: "cargo", package: "ring", version: "0.17.8", licence: "MIT AND ISC", evidence: "the crate's LICENSE", read: "2026-11-18", licence_file: { path: "LICENSE", sha256: SHA, cargo_deny_hash: "0xbd0eed23" } }],
        class_overrides: [{ ecosystem: "cargo", package: "some-font-crate", class: "F", why: "bundles OFL fonts" }],
      }),
    ),
  );
  assert.match(files["deny.toml"], /\[\[licenses\.clarify\]\]\ncrate = "ring@0\.17\.8"\nexpression = "MIT AND ISC"\nlicense-files = \[\{ path = "LICENSE", hash = 0xbd0eed23 \}\]/);
  assert.match(files["deny.toml"], /\[\[licenses\.exceptions\]\]\ncrate = "some-font-crate"\nallow = \[\n {2}"OFL-1\.1",/);
  assert.match(files["about.toml"], /\[ring\.clarify\]\nlicense = "MIT AND ISC"\n\n\[\[ring\.clarify\.files\]\]\npath = "LICENSE"\nchecksum = "b{64}"/);
  assert.match(files["about.toml"], /\[some-font-crate\]\naccepted = \[\n {2}"OFL-1\.1",/);
  assert.match(files[".github/dependency-review-config.yml"], /allow-dependencies-licenses:\n {2}- 'pkg:cargo\/some-font-crate'/);
});

test("Luka's own crates (own_sources, S-27) pass a gpl-le gate by source while class L still takes no GPL", () => {
  const own = [{ ecosystem: "cargo", source: "https://github.com/example/kit", crates: ["kit-updater", "kit-theme"], licence: "GPL-3.0-or-later", why: "S-27 kit crates" }];
  const policy = compilePolicy(policyFor("gpl-le", { own_sources: own }));
  assert.deepEqual(policy.problems, []);
  const files = render(policy);
  const deny = files["deny.toml"];
  assert.match(deny, /\[\[licenses\.exceptions\]\]\ncrate = "kit-updater"\nallow = \[\n {2}"GPL-3\.0-or-later",\n\]/, "a missing exception fails the consumer's cargo-deny");
  assert.match(deny, /crate = "kit-theme"/);
  assert.match(deny, /allow-git = \["https:\/\/github\.com\/example\/kit"\]/, "an unlisted source fails unknown-git");
  assert.doesNotMatch(deny.split("[licenses.private]")[0].replace(/^#.*$/gm, ""), /GPL-/, "class L of gpl-le stays free of GPL");
  assert.match(files["about.toml"], /\[kit-updater\]\naccepted = \[\n {2}"GPL-3\.0-or-later",\n\]/);
  assert.match(files[".github/dependency-review-config.yml"], /allow-dependencies-licenses:[\s\S]*- 'pkg:cargo\/kit-updater'/);
  assert.match(
    compilePolicy(policyFor("reserved", { own_sources: own })).problems.join("\n"),
    /profile reserved takes no GPL crates/,
    "the CV's reserved profile must not take GPL code through this door",
  );
  assert.match(compilePolicy(policyFor("gpl", { own_sources: [{ ...own[0], licence: "MIT" }] })).problems.join("\n"), /names MIT/);
  assert.throws(() => compilePolicy(policyFor("gpl", { own_sources: [{ ...own[0], source: "git@github.com:x/y" }] })), /an own_sources entry needs/);
  assert.throws(
    () => compilePolicy(policyFor("gpl", { own_sources: own, class_overrides: [{ ecosystem: "cargo", package: "kit-theme", class: "F", why: "w" }] })),
    /kit-theme is in own_sources and also in class_overrides/,
  );
});

const GHSA_ENTRY = { id: "GHSA-84m7-p3x7-pcfv", reason: "mcp 1.29.0, pinned by a tool; its server transport is never started.", until: "2027-01-15" };

test("allow_ghsas reach the dependency review as allow-ghsas, each with its reason and review date above it; an empty list writes nothing; no other file carries an id", () => {
  const none = render(compilePolicy(policyFor("gpl")));
  assert.doesNotMatch(none[".github/dependency-review-config.yml"], /allow-ghsas/, "an empty list must leave the config as it was");
  const files = render(compilePolicy(policyFor("gpl", { allow_ghsas: [GHSA_ENTRY, { ...GHSA_ENTRY, id: "GHSA-qx49-fqc8-xw99", reason: "its OAuth client is never started.", until: "2027-02-01" }] })));
  assert.match(
    files[".github/dependency-review-config.yml"],
    /\nallow-ghsas:\n {2}# mcp 1\.29\.0, pinned by a tool; its server transport is never started\. Review by 2027-01-15\.\n {2}- 'GHSA-84m7-p3x7-pcfv'\n {2}# its OAuth client is never started\. Review by 2027-02-01\.\n {2}- 'GHSA-qx49-fqc8-xw99'\n$/,
  );
  for (const [path, text] of Object.entries(files)) {
    if (path !== ".github/dependency-review-config.yml") assert.doesNotMatch(text, /GHSA/, `${path} must not carry an advisory id`);
  }
});

test("a malformed allow_ghsas entry is refused as a malformed policy, and nothing is written", () => {
  const bad = {
    "an id that is not a GHSA id": { ...GHSA_ENTRY, id: "CVE-2026-0001" },
    "an id with a character GHSA ids never use": { ...GHSA_ENTRY, id: "GHSA-84m7-p3x7-pcfa" },
    "an id in lower case": { ...GHSA_ENTRY, id: "ghsa-84m7-p3x7-pcfv" },
    "no reason": { ...GHSA_ENTRY, reason: "" },
    "a reason of spaces": { ...GHSA_ENTRY, reason: "   " },
    "a reason on two lines": { ...GHSA_ENTRY, reason: "first\nsecond" },
    "no review date": { id: GHSA_ENTRY.id, reason: GHSA_ENTRY.reason },
    "a review date that is not YYYY-MM-DD": { ...GHSA_ENTRY, until: "2027-1-15" },
    "a bare id in place of an entry": GHSA_ENTRY.id,
  };
  for (const [what, entry] of Object.entries(bad)) {
    assert.throws(() => compilePolicy(policyFor("gpl", { allow_ghsas: [entry] })), /an allow_ghsas entry needs id/, what);
  }
  assert.throws(() => compilePolicy(policyFor("gpl", { allow_ghsas: [GHSA_ENTRY, { ...GHSA_ENTRY }] })), /GHSA-84m7-p3x7-pcfv is listed twice in allow_ghsas/);
  assert.throws(() => compilePolicy(policyFor("gpl", { allow_ghsas: {} })), /allow_ghsas must be a list/);
  const r = repo(policyFor("gpl", { allow_ghsas: [{ ...GHSA_ENTRY, reason: "" }] }));
  try {
    for (const mode of ["--write", "--check"]) {
      const g = r.gen(mode);
      assert.equal(g.code, 2, `${mode}: ${g.out}`);
      assert.match(g.out, /an allow_ghsas entry needs id/);
    }
    assert.ok(!existsSync(join(r.dir, ".github", "dependency-review-config.yml")), "nothing is written");
  } finally {
    r.cleanup();
  }
});

const nugetClarification = (pkg, version, licence, path) => ({ ecosystem: "nuget", package: pkg, version, licence, evidence: "the package's licence file", read: "2026-11-18", licence_file: { path, sha256: SHA } });

test("NuGet clarifications reach nuget-license's override file as { Id, Version, License }, sorted, and no other ecosystem does", () => {
  const files = render(
    compilePolicy(
      policyFor("gpl", {
        clarifications: [
          nugetClarification("Zeta.Lib", "2.0.0", "MIT", "~/.nuget/packages/zeta.lib/2.0.0/LICENSE.txt"),
          nugetClarification("Alpha.Lib", "1.4.0", "BSD-3-Clause", "{path}/LICENSE.txt"),
          { ecosystem: "npm", package: "odd", version: "1.0.0", licence: "MIT", evidence: "e", read: "2026-11-18", licence_file: { path: "L", sha256: SHA } },
        ],
      }),
    ),
  );
  assert.deepEqual(JSON.parse(files[".github/nuget-license/overrides.json"]), [
    { Id: "Alpha.Lib", Version: "1.4.0", License: "BSD-3-Clause" },
    { Id: "Zeta.Lib", Version: "2.0.0", License: "MIT" },
  ]);
});

// overrides.json is compared byte for byte by --check on CI (ubuntu-24.04 in ci-rust.yml, windows-2025 in ci-dotnet.yml), so
// its order may not depend on the machine's locale. localeCompare with no locale follows the default ICU locale: on en-US
// it puts "a_b.lib" before "a1.lib", and in sr-Latn or hr "lj" and "nj" are letters of their own. Code-unit order is the
// same everywhere: "1" (0x31) comes before "_" (0x5F), and "B" (0x42) before "a" (0x61) (B0-U01).
test("the NuGet overrides are sorted by code unit, never by the machine's locale: a1.lib before a_b.lib, and a version 1.0.0-Beta before 1.0.0-alpha (B0-U01)", () => {
  const home = (id, version) => `~/.nuget/packages/${id}/${version.toLowerCase()}/LICENSE.txt`;
  const files = render(
    compilePolicy(
      policyFor("gpl", {
        clarifications: [
          nugetClarification("a_b.lib", "1.0.0", "MIT", home("a_b.lib", "1.0.0")),
          nugetClarification("same.lib", "1.0.0-alpha", "MIT", home("same.lib", "1.0.0-alpha")),
          nugetClarification("a1.lib", "1.0.0", "MIT", home("a1.lib", "1.0.0")),
          nugetClarification("same.lib", "1.0.0-Beta", "MIT", home("same.lib", "1.0.0-Beta")),
        ],
      }),
    ),
  );
  assert.deepEqual(
    JSON.parse(files[".github/nuget-license/overrides.json"]).map((o) => `${o.Id}@${o.Version}`),
    ["a1.lib@1.0.0", "a_b.lib@1.0.0", "same.lib@1.0.0-Beta", "same.lib@1.0.0-alpha"],
  );
});

// overrides.json gives a NuGet package its licence by id and version, whatever the package's own licence file holds
// (nuget-license 4.0.18 reports it with origin 4, the override). A committed copy as the pin hashes only the copy, so a
// changed installed file passed the gate (B0-U13, 2026-11-25). A NuGet clarification therefore names the installed file,
// which check-licences.mjs hashes, and a committed copy is a malformed policy (exit 2), in every spelling of a path from
// the repository root. An absolute path is refused too: it reaches a committed copy through the checkout's own path, or
// it names a file on one machine only. The other ecosystems keep their path forms.
test("a NuGet clarification pinned by a committed copy or an absolute path is refused (exit 2) and nothing is written; the installed file, {path} and ~/ forms pass, and the licence-file mapping stays empty (B0-U13)", () => {
  const refused = {
    "a copy in the repository": ["third_party/licences/Zeta.Lib.txt", "./third_party/licences/Zeta.Lib.txt", "third_party\\licences\\Zeta.Lib.txt", "LICENSE.txt"],
    "an absolute path": ["/home/runner/work/app/app/third_party/licences/Zeta.Lib.txt", "C:\\Users\\me\\.nuget\\packages\\zeta.lib\\2.0.0\\LICENSE.txt", "D:/a/app/app/LICENSE.txt"],
  };
  for (const [what, paths] of Object.entries(refused)) {
    for (const path of paths) {
      assert.throws(
        () => compilePolicy(policyFor("gpl", { clarifications: [nugetClarification("Zeta.Lib", "2.0.0", "MIT", path)] })),
        (e) => e.message.includes(`the NuGet clarification for Zeta.Lib@2.0.0 pins ${path}, ${what}`) && /~\/\.nuget\/packages\/<id in lower case>\/<version in lower case>\/<file>/.test(e.message),
        path,
      );
    }
  }
  const r = repo(policyFor("gpl", { clarifications: [nugetClarification("Zeta.Lib", "2.0.0", "MIT", "third_party/licences/Zeta.Lib.txt")] }));
  try {
    for (const mode of ["--write", "--check"]) {
      const g = r.gen(mode);
      assert.equal(g.code, 2, `${mode}: ${g.out}`);
      assert.match(g.out, /the NuGet clarification for Zeta\.Lib@2\.0\.0 pins third_party\/licences\/Zeta\.Lib\.txt, a copy in the repository/);
    }
    assert.ok(!existsSync(join(r.dir, ".github", "nuget-license", "overrides.json")), "nothing is written");
  } finally {
    r.cleanup();
  }
  const files = render(
    compilePolicy(
      policyFor("gpl", {
        clarifications: [
          nugetClarification("Home.Lib", "1.0.0", "ISC", "~/.nuget/packages/home.lib/1.0.0/LICENSE"),
          nugetClarification("Back.Lib", "1.0.0", "MIT", "~\\.nuget\\packages\\back.lib\\1.0.0\\LICENSE.txt"),
          nugetClarification("Alpha.Lib", "1.4.0", "BSD-3-Clause", "{path}/LICENSE.txt"),
          { ecosystem: "npm", package: "odd", version: "1.0.0", licence: "MIT", evidence: "e", read: "2026-11-18", licence_file: { path: "third_party/odd/LICENSE", sha256: SHA } },
        ],
      }),
    ),
  );
  assert.deepEqual(JSON.parse(files[".github/nuget-license/overrides.json"]).map((o) => o.Id), ["Alpha.Lib", "Back.Lib", "Home.Lib"]);
  assert.equal(files[".github/nuget-license/licensefile-mappings.json"], "{}\n", "no committed copy can be mapped, so the mapping file is the empty object");
});

test("an entry with a licence the policy does not list fails, and nothing is written", () => {
  const r = repo(policyFor("gpl", { clarifications: [{ ecosystem: "npm", package: "odd", version: "1.0.0", licence: "Foo-1.0", evidence: "e", read: "2026-11-18", licence_file: { path: "L", sha256: SHA } }] }));
  try {
    const w = r.gen("--write");
    assert.equal(w.code, 1, w.out);
    assert.match(w.out, /the clarification for odd@1\.0\.0 names Foo-1\.0.*Foo-1\.0 is not on the allow list of class L of profile gpl/);
    assert.ok(!existsSync(join(r.dir, "deny.toml")));
  } finally {
    r.cleanup();
  }
});

test("a denied licence prints its reason: in an entry and in a self-contradicting allow list", () => {
  const platform = [...structuredClone(TEMPLATE.platform), { name: "Thing", kind: "toolchain-runtime", licence: "GPL-2.0-only", source: "s", licence_file: "COPYING", sha256: null, duties: [], why: "w" }];
  const p1 = compilePolicy(policyFor("gpl", { platform }));
  assert.match(p1.problems.join("\n"), /the platform entry Thing \(toolchain-runtime\) carries GPL-2\.0-only.*GPL-2\.0-only: GPL-incompatible in linked code/);
  const bad = policyFor("gpl");
  bad.allow.L.common.push("Ubuntu-font-1.0");
  const r = repo(bad);
  try {
    const w = r.gen("--write");
    assert.equal(w.code, 1, w.out);
    assert.match(w.out, /allow\.L lists Ubuntu-font-1\.0, which deny also matches.*PG-D6/);
  } finally {
    r.cleanup();
  }
});

test("the template placeholder profile is refused with a clear message, and nothing is written", () => {
  // Not the repository's own policy file: after adoption its profile is set and this case would not see a placeholder.
  const r = repo({ ...structuredClone(TEMPLATE), profile: PLACEHOLDER_PROFILE, generate: OUTPUTS });
  try {
    for (const mode of ["--write", "--check"]) {
      const g = r.gen(mode);
      assert.equal(g.code, 2, g.out);
      assert.match(g.out, /profile is still the template placeholder .*: set "profile" to one of gpl, gpl-le, reserved, permissive/);
    }
    assert.ok(!existsSync(join(r.dir, "deny.toml")));
  } finally {
    r.cleanup();
  }
});

test("usage errors: no mode, both modes, an unreadable policy", () => {
  const r = repo(policyFor("gpl"));
  try {
    assert.equal(run("licence-configs.mjs", [], r.dir).code, 2);
    assert.equal(run("licence-configs.mjs", ["--write", "--check"], r.dir).code, 2);
    r.write(".github/licence-policy.json", "not json");
    assert.equal(r.gen("--check").code, 2);
  } finally {
    r.cleanup();
  }
});

test("the configs committed beside this script are what the policy generates", () => {
  // In the template the profile is the placeholder and the committed configs are profile gpl's;
  // in an adopted repository this repeats --check.
  const policy = structuredClone(TEMPLATE);
  if (policy.profile.includes("{{tpl:")) policy.profile = "gpl";
  const files = render(compilePolicy(policy));
  for (const [path, text] of Object.entries(files)) {
    assert.equal(readFileSync(join(REPO, path), "utf8").replace(/\r\n/g, "\n"), text, `${path} is stale: run the generator`);
  }
});
